import { Component, Element, Event, EventEmitter, Host, Prop, State, Watch, h } from '@stencil/core';
import { AriaAttributes, extractAriaAttributes } from '../../utils/a11y-helper';

@Component({
  tag: 'groupui-progress',
  styleUrl: 'progress.scss',
  shadow: true,
})
export class Progress {
  /**
   * activates an inverted presentation
   */
  @Prop({ reflect: true }) readonly inverted: boolean = false;

  /**
   * defines the percentage of the progress
   */
  @Prop({ reflect: true }) readonly progress: number;

  /**
   * the size of the progress
   */
  @Prop({ reflect: true }) readonly size: 's' | 'm' | 'l' | 'xl' | 'xxl' | '3xl' = 'm';

  /**
   * dispatched when component finished loading
   */
  @Event({ bubbles: false }) groupuiDidLoad: EventEmitter<void>;

  /**
   * toggle embedded mode for use inside other components
   */
  @Prop({ reflect: true }) readonly embedded: boolean;

  /**
   * disables the background color
   */
  @Prop({ reflect: true }) readonly noTrack: boolean = false;

  @Element() host: HTMLElement;

  @State() ariaAttributes: AriaAttributes;

  componentWillLoad() {
    this.updateSize();
    this.updateStrokeWidth();
    this.updateProgress();
    this.ariaAttributes = extractAriaAttributes(this.host);
  }

  componentDidLoad() {
    this.groupuiDidLoad.emit();
  }

  @Watch('size')
  onSizeChanged() {
    this.updateSize();
    this.updateStrokeWidth();
  }

  @Watch('progress')
  onProgressChanged() {
    this.updateProgress();
  }

  private updateSize() {
    let circleDiameter: string;
    let margin: string;
    switch (this.size) {
      case 's':
        margin = '1px';
        circleDiameter = `calc(var(--groupui-sys-spacing-400) - calc(2 * ${margin}))`;
        break;
      case 'l':
        margin = '3px';
        circleDiameter = `calc(var(--groupui-sys-spacing-800) - calc(2 * ${margin}))`;
        break;
      case 'xl':
        margin = '4px';
        circleDiameter = `calc(var(--groupui-sys-spacing-1200) - calc(2 * ${margin}))`;
        break;
      case 'xxl':
        margin = '4px';
        circleDiameter = `calc(var(--groupui-sys-spacing-2400) - calc(2 * ${margin}))`;
        break;
      case '3xl':
        margin = '4px';
        circleDiameter = `calc(var(--groupui-sys-spacing-3400) - calc(2 * ${margin}))`;
        break;
      case 'm':
      default:
        margin = '2px';
        circleDiameter = `calc(var(--groupui-sys-spacing-600) - calc(2 * ${margin}))`;
        break;
    }
    this.host.style.setProperty('--circle-diameter', circleDiameter);
    this.host.style.setProperty('--margin', margin);
  }

  private updateStrokeWidth() {
    let strokeWidthToken;
    switch (this.size) {
      case 'xxl':
        strokeWidthToken = 'var(--groupui-sys-border-width-xl)';
        break;
      case '3xl':
        strokeWidthToken = 'var(--groupui-sys-border-width-xxxl)';
        break;
      case 's':
      case 'm':
      case 'l':
      case 'xl':
      default:
        strokeWidthToken = 'var(--groupui-sys-border-width-m)';
        break;
    }
    this.host.style.setProperty('--circle-stroke-width', strokeWidthToken);
  }

  private updateProgress() {
    this.host.style.setProperty('--progress', String(this.progress / 100));
  }

  render() {
    return (
      <Host>
        {this.progress !== undefined && this.progress !== null ? (
          <svg
            id="loading"
            role="progressbar"
            aria-live="polite"
            aria-valuemin="0"
            aria-valuemax="100"
            aria-valuenow={this.progress}
            aria-label="circular"
            {...this.ariaAttributes}
          >
            <circle id="circle-track" />
            <circle id="circle-fill" />
          </svg>
        ) : (
          <div role="progressbar" aria-valuemin="0" aria-valuemax="100" aria-label="circular" {...this.ariaAttributes}>
            <groupui-loading
              no-track={this.noTrack}
              size={this.size}
              inverted={this.inverted}
              embedded={this.embedded}
            ></groupui-loading>
          </div>
        )}
      </Host>
    );
  }
}
